/**
 * Tenant branding (interpretation engine, P4c): a tenant may set a product name and a logo, and nothing else. The
 * governance statement, status banner and referral advisory are generated by code and are not reachable from here.
 *
 *   product name  1-60 characters: letters, digits, space and . , & ' ( ) -   (no markup, no control characters)
 *   logo          PNG or JPEG only, at most 256 KB decoded; the type is decided by the file's own bytes, never by what the
 *                 caller says. SVG is refused (it can carry script).
 */
import { db } from '../../db';
import { TenancyError } from '../tenancy/keys';
import { AuditCtx, ensureTenantAuditReady, recordTenantEvent } from '../tenancy/audit';
import type { Branding } from './render';

export const MAX_LOGO_BYTES = 256 * 1024;
const NAME_RE = /^[\p{L}\p{N}][\p{L}\p{N} .,&'()-]{0,59}$/u;
const B64_RE = /^[A-Za-z0-9+/]+={0,2}$/;

export function sniffImage(buf: Buffer): 'image/png' | 'image/jpeg' | null {
  if (buf.length >= 8 && buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return 'image/png';
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'image/jpeg';
  return null;
}

export interface BrandingUpdate { productName?: string | null; logoBase64?: string | null }

export function parseBrandingUpdate(body: unknown): { productName?: string | null; logo?: { mime: 'image/png' | 'image/jpeg'; base64: string } | null } {
  const b = (body ?? {}) as Record<string, unknown>;
  for (const k of Object.keys(b)) if (!['productName', 'logoBase64'].includes(k)) throw new TenancyError(400, 'validation_failed', `Unknown field "${k}". Only productName and logoBase64 can be set.`);
  const out: { productName?: string | null; logo?: { mime: 'image/png' | 'image/jpeg'; base64: string } | null } = {};
  if ('productName' in b) {
    if (b.productName === null) out.productName = null;
    else if (typeof b.productName === 'string' && NAME_RE.test(b.productName.trim()) && b.productName.trim().length <= 60) out.productName = b.productName.trim();
    else throw new TenancyError(400, 'validation_failed', 'productName must be 1-60 characters: letters, digits, spaces and . , & \' ( ) -');
  }
  if ('logoBase64' in b) {
    if (b.logoBase64 === null) out.logo = null;
    else {
      if (typeof b.logoBase64 !== 'string' || b.logoBase64.length > Math.ceil(MAX_LOGO_BYTES / 3) * 4 + 4 || !B64_RE.test(b.logoBase64)) throw new TenancyError(400, 'validation_failed', 'logoBase64 must be base64 of a PNG or JPEG of at most 256 KB.');
      const buf = Buffer.from(b.logoBase64, 'base64');
      if (buf.length === 0 || buf.length > MAX_LOGO_BYTES) throw new TenancyError(400, 'validation_failed', 'The logo must be at most 256 KB.');
      const mime = sniffImage(buf);
      if (!mime) throw new TenancyError(400, 'validation_failed', 'The logo must be a PNG or JPEG image.');
      out.logo = { mime, base64: buf.toString('base64') };
    }
  }
  if (!('productName' in out) && !('logo' in out)) throw new TenancyError(400, 'validation_failed', 'Send productName and/or logoBase64.');
  return out;
}

export async function getBranding(tenantId: string): Promise<Branding> {
  const r = await db.queryOne<{ product_name: string | null; logo_mime: 'image/png' | 'image/jpeg' | null; logo_base64: string | null }>('SELECT product_name, logo_mime, logo_base64 FROM tenant_branding WHERE tenant_id = $1', [tenantId]);
  return r ? { productName: r.product_name, logoMime: r.logo_mime, logoBase64: r.logo_base64 } : {};
}

export async function setBranding(tenantId: string, upd: ReturnType<typeof parseBrandingUpdate>, ctx: AuditCtx, now = Date.now()): Promise<Branding> {
  const tenant = await db.queryOne('SELECT 1 FROM tenants WHERE tenant_id = $1', [tenantId]);
  if (!tenant) throw new TenancyError(404, 'tenant_not_found', 'Tenant not found.');
  await ensureTenantAuditReady();
  await db.transaction(async (tx) => {
    await tx.query('INSERT INTO tenant_branding (tenant_id, updated_at) VALUES ($1,$2) ON CONFLICT (tenant_id) DO NOTHING', [tenantId, now]);
    if ('productName' in upd) await tx.query('UPDATE tenant_branding SET product_name = $2, updated_at = $3 WHERE tenant_id = $1', [tenantId, upd.productName ?? null, now]);
    if ('logo' in upd) await tx.query('UPDATE tenant_branding SET logo_mime = $2, logo_base64 = $3, updated_at = $4 WHERE tenant_id = $1', [tenantId, upd.logo?.mime ?? null, upd.logo?.base64 ?? null, now]);
    await recordTenantEvent(tx, tenantId, ctx, 'tenant.branding_updated', { product_name_changed: 'productName' in upd, logo_changed: 'logo' in upd, logo_cleared: 'logo' in upd && upd.logo === null });
  });
  return getBranding(tenantId);
}

export async function clearBranding(tenantId: string, ctx: AuditCtx): Promise<void> {
  await ensureTenantAuditReady();
  await db.transaction(async (tx) => {
    await tx.query('DELETE FROM tenant_branding WHERE tenant_id = $1', [tenantId]);
    await recordTenantEvent(tx, tenantId, ctx, 'tenant.branding_cleared', {});
  });
}

/** What an administrator sees: never the logo bytes. */
export function brandingView(b: Branding): { productName: string | null; hasLogo: boolean; logoMime: string | null } {
  return { productName: b.productName ?? null, hasLogo: !!b.logoBase64, logoMime: b.logoMime ?? null };
}
